use super::{field, literal, method, ty};
use crucible_smithy::ir::{Service, Shape};

pub fn emit(service: &Service, module: &str) -> String {
    let mut out = format!(
        "// Generated by Crucible. DO NOT EDIT.\nimport Foundation\n\npublic enum Models {{\n    public struct Unit: Swift.Sendable, {module}.WireCodable {{\n        public init() {{}}\n        static func fromWire(_ value: {module}.JSONValue, _ context: {module}.WireContext) throws -> Self {{\n            guard try value.object.isEmpty else {{ throw {module}.WireError(\"Unit requires an empty object\") }}; return Self()\n        }}\n        func toWire(_ context: {module}.WireContext) throws -> {module}.JSONValue {{ .object([:]) }}\n    }}\n"
    );
    let mut errors = format!(
        "\ninternal enum ModeledErrors {{\n    static func decode(_ target: Swift.String, value: {module}.JSONValue, codec: {module}.WireCodec, metadata: {module}.ErrorMetadata) throws -> any {module}.ServiceError {{\n        switch target {{\n"
    );
    for (id, shape) in &service.shapes {
        if id.is_prelude() || matches!(shape, Shape::Simple(_) | Shape::Unit) {
            continue;
        }
        let name = service.name_of(id);
        match shape {
            Shape::List(list) => out.push_str(&format!(
                "    public typealias `{name}` = Swift.Array<{}>\n",
                ty(service, &list.member.target, module)
            )),
            Shape::Map(map) => out.push_str(&format!(
                "    public typealias `{name}` = Swift.Dictionary<{}, {}>\n",
                ty(service, &map.key.target, module),
                ty(service, &map.value.target, module)
            )),
            Shape::Enum(enumeration) => {
                out.push_str(&format!("    public struct `{name}`: Swift.RawRepresentable, Swift.Hashable, Swift.Sendable, {module}.WireCodable {{\n        public let rawValue: Swift.String\n        public init(rawValue: Swift.String) {{ self.rawValue = rawValue }}\n"));
                for value in &enumeration.values {
                    out.push_str(&format!(
                        "        public static let `{}` = Self(rawValue: {})\n",
                        method(&value.name),
                        literal(&value.value)
                    ));
                }
                out.push_str(&format!("        static func fromWire(_ value: {module}.JSONValue, _ context: {module}.WireContext) throws -> Self {{ Self(rawValue: try value.string) }}\n        func toWire(_ context: {module}.WireContext) throws -> {module}.JSONValue {{ .string(rawValue) }}\n    }}\n"));
            }
            Shape::Structure(structure) => {
                let error = if structure.error.is_some() {
                    format!(", {module}.ServiceError")
                } else {
                    String::new()
                };
                out.push_str(&format!(
                    "    public struct `{name}`: Swift.Sendable, {module}.WireCodable{error} {{\n"
                ));
                let mut parameters = Vec::new();
                for member in &structure.members {
                    let field = field(&member.name);
                    let value_type = ty(service, &member.target, module);
                    let value_type = if member.optional_on_client() {
                        format!("{module}.OptionalValue<{value_type}>")
                    } else {
                        value_type
                    };
                    out.push_str(&format!("        public var `{field}`: {value_type}\n"));
                    parameters.push(format!(
                        "`{field}`: {value_type}{}",
                        if member.optional_on_client() {
                            " = .unset"
                        } else {
                            ""
                        }
                    ));
                }
                if structure.error.is_some() {
                    out.push_str(&format!(
                        "        public var metadata: {module}.ErrorMetadata\n"
                    ));
                    parameters.push(format!(
                        "metadata: {module}.ErrorMetadata = {module}.ErrorMetadata()"
                    ));
                }
                out.push_str(&format!(
                    "        public init({}) {{\n",
                    parameters.join(", ")
                ));
                for member in &structure.members {
                    let field = field(&member.name);
                    out.push_str(&format!("            self.`{field}` = `{field}`\n"));
                }
                if structure.error.is_some() {
                    out.push_str("            self.metadata = metadata\n");
                }
                out.push_str(&format!("        }}\n        static func fromWire(_ value: {module}.JSONValue, _ context: {module}.WireContext) throws -> Self {{\n"));
                if !structure.members.is_empty() {
                    out.push_str("            let object = try value.object\n");
                } else {
                    out.push_str("            _ = try value.object\n");
                }
                out.push_str(if structure.members.is_empty() {
                    "            return Self(\n"
                } else {
                    "            return try Self(\n"
                });
                for (index, member) in structure.members.iter().enumerate() {
                    let field = field(&member.name);
                    let read = if member.optional_on_client() {
                        "optional"
                    } else {
                        "read"
                    };
                    out.push_str(&format!("                {field}: context.codec.{read}(context.target, {}, object, as: {}.self){}\n", literal(&member.name), ty(service, &member.target, module), if index + 1 == structure.members.len() { "" } else { "," }));
                }
                out.push_str(&format!("            )\n        }}\n        func toWire(_ context: {module}.WireContext) throws -> {module}.JSONValue {{\n"));
                if structure.members.is_empty() {
                    out.push_str("            return .object([:])\n");
                } else {
                    out.push_str(&format!(
                        "            var object: [Swift.String: {module}.JSONValue] = [:]\n"
                    ));
                    for member in &structure.members {
                        out.push_str(&format!("            try context.codec.put(context.target, {}, self.`{}`, into: &object)\n", literal(&member.name), field(&member.name)));
                    }
                    out.push_str("            return .object(object)\n");
                }
                out.push_str("        }\n    }\n");
                if structure.error.is_some() {
                    errors.push_str(&format!("        case {}:\n            var error = try {module}.Models.`{name}`.fromWire(value, codec.context(target))\n            error.metadata = metadata; return error\n", literal(&id.to_string())));
                }
            }
            Shape::Union(union) => {
                out.push_str(&format!(
                    "    public indirect enum `{name}`: Swift.Sendable, {module}.WireCodable {{\n"
                ));
                for member in &union.members {
                    out.push_str(&format!(
                        "        case `{}`({}?)\n",
                        method(&member.name),
                        ty(service, &member.target, module)
                    ));
                }
                out.push_str(&format!("        case unknownVariant(name: Swift.String, value: {module}.JSONValue)\n        static func fromWire(_ value: {module}.JSONValue, _ context: {module}.WireContext) throws -> Self {{\n            let object = try value.object\n            guard object.count == 1, let (name, item) = object.first else {{ throw {module}.WireError(\"Union requires one member\") }}\n            switch name {{\n"));
                for member in &union.members {
                    out.push_str(&format!("            case {}: return .`{}`(item == .null ? nil : try {}.fromWire(item, context.child(context.codec.member(context.target, name))))\n", literal(&member.name), method(&member.name), ty(service, &member.target, module)));
                }
                out.push_str(&format!("            default: return .unknownVariant(name: name, value: item)\n            }}\n        }}\n        func toWire(_ context: {module}.WireContext) throws -> {module}.JSONValue {{\n            switch self {{\n"));
                for member in &union.members {
                    let name = literal(&member.name);
                    out.push_str(&format!("            case .`{}`(let value): return .object([{name}: try value?.toWire(context.child(context.codec.member(context.target, {name}))) ?? .null])\n", method(&member.name)));
                }
                out.push_str(&format!("            case .unknownVariant(let name, let value):\n                guard try context.shape[\"members\"]?[name] == nil else {{ throw {module}.WireError(\"Unknown variant name is declared\") }}\n                return .object([name: value])\n            }}\n        }}\n    }}\n"));
            }
            _ => unreachable!(),
        }
    }
    out.push_str("}\n");
    errors.push_str(&format!("        default: return {module}.UnknownServiceError(metadata: metadata)\n        }}\n    }}\n}}\n"));
    out.push_str(&errors);
    out
}
